// ---------------------------------------------------------------------------
// Read the file and process each language
// ---------------------------------------------------------------------------
const raw = fs.readFileSync(I18N_PATH, 'utf8');
// Detect line ending (sitetrace repo uses CRLF on Windows).
const hasCRLF = raw.indexOf('\r\n') !== -1;
const EOL = hasCRLF ? '\r\n' : '\n';
// Normalize the working buffer to LF for easy string ops, then restore
// the original EOL on write.
const src = raw.replace(/\r\n/g, '\n');

const ctaLines = {
  en: "      front_feature_seo_cta: 'Check any URL →',",
  es: "      front_feature_seo_cta: 'Comprobar URL →',",
  pt: "      front_feature_seo_cta: 'Verificar URL →',",
  fr: "      front_feature_seo_cta: 'Vérifier une URL →',",
  de: "      front_feature_seo_cta: 'URL prüfen →',",
  it: "      front_feature_seo_cta: 'Controlla un URL →',",
  ja: "      front_feature_seo_cta: 'URLをチェック →',",
  zh: "      front_feature_seo_cta: '检查URL →',",
};

let out = src;
let changes = 0;

for (const lang of Object.keys(BLOCKS)) {
  const cta = ctaLines[lang];
  const block = BLOCKS[lang].replace(/\r\n/g, '\n').replace(/\n/g, EOL);
  // Anchor: cta line + the closing `    },` of the language block.
  // We want to insert the iprep_* block between them, so the closing
  // `    },` stays the last thing in the language block.
  const anchor = cta + '\n    },';
  if (out.indexOf(anchor) === -1) {
    // Could be that the block already has iprep_* keys (idempotent re-run).
    const langBlockRegex = new RegExp('    ' + lang + ': \\{');
    const m = out.match(langBlockRegex);
    if (m) {
      const startIdx = m.index;
      const rest = out.slice(startIdx);
      const endMatch = rest.match(/\n    \},\n/);
      if (endMatch && rest.indexOf('iprep_h1:') !== -1 && rest.indexOf('iprep_h1:') < endMatch.index) {
        console.log('[' + lang + '] iprep_* already present, skipping');
        continue;
      }
    }
    console.error('[' + lang + '] could not find anchor:\n' + anchor);
    process.exit(1);
  }
  // Insert block: cta line, blank line, iprep block, blank line, `    },`
  const replacement = cta + '\n\n' + block + '    },';
  out = out.replace(anchor, replacement);
  changes += 1;
  console.log('[' + lang + '] inserted ' + (block.match(/iprep_/g) || []).length + ' iprep_* keys');
}

if (changes === 0) {
  console.log('No changes made.');
} else {
  // Restore the original line endings on write.
  const outFinal = out.replace(/\n/g, EOL);
  fs.writeFileSync(I18N_PATH, outFinal, 'utf8');
  console.log('\nWrote ' + I18N_PATH + ' (' + changes + ' languages updated)');
}
